patch:
diff --git a/repro/no-var-tdz.js b/repro/no-var-tdz.js
new file mode 100644
index 0000000..f591a0e
--- /dev/null
+++ b/repro/no-var-tdz.js
@@ -0,0 +1,39 @@
+"use strict";
+// Repro for no-var autofix turning `var` used-before-declaration into `let` (TDZ ReferenceError).
+// Usage: node repro/no-var-tdz.js [path-to-eslint-package-root]   (default: this checkout)
+const path = require("node:path");
+const vm = require("node:vm");
+
+const root = path.resolve(process.argv[2] || path.join(__dirname, ".."));
+const { Linter } = require(path.join(root, "lib/api"));
+const version = require(path.join(root, "package.json")).version;
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}`;
+const config = [{ rules: { "no-var": ["error"] } }];
+
+const linter = new Linter({ configType: "flat" });
+const messages = linter.verify(code, config, "x.js");
+const { output, fixed } = linter.verifyAndFix(code, config, "x.js");
+
+function run(src) {
+    const body = src.replace(/^export /u, "");
+    try {
+        vm.runInNewContext(`${body}\na();`, { console: { log() {} } });
+        return "ok";
+    } catch (e) {
+        return `${e.name}: ${e.message}`;
+    }
+}
+
+console.log(`eslint ${version}`);
+console.log("messages:", messages.map(m => `${m.line}:${m.column} ${m.message} (${m.ruleId}) fix=${!!m.fix}`));
+console.log(`fixed: ${fixed}\n--- output ---\n${output}\n--------------`);
+console.log("run original:", run(code));
+console.log("run output:  ", run(output));
+const bug = fixed && run(output) !== "ok";
+console.log(bug ? "BUG REPRODUCED: autofix introduced a ReferenceError" : "no bug: fix is unsafe-guarded or not applied");
+process.exitCode = bug ? 1 : 0;
